import{_ as t,I as i,c as n,o,j as e,ap as d,a as r,J as h}from"./chunks/framework.BVMg0REN.js";const _=JSON.parse('{"title":"下载安装","description":"","frontmatter":{},"headers":[],"relativePath":"FAQ/02-installation-issues.md","filePath":"zh/FAQ/02-installation-issues.md","lastUpdated":1786187251000}'),s={name:"FAQ/02-installation-issues.md"},c={id:"下载安装",tabindex:"-1"};function p(m,a,b,f,u,k){const l=i("Badge");return o(),n("div",null,[e("h1",c,[a[0]||(a[0]=r("下载安装")),h(l,{type:"danger",text:"问题"}),a[1]||(a[1]=r()),a[2]||(a[2]=e("a",{class:"header-anchor",href:"#下载安装","aria-label":"Permalink to “下载安装”"},"​",-1))]),a[3]||(a[3]=d('<div class="tip custom-block"><p class="custom-block-title">阅读提示</p><p>第一次使用 MaaYuan 时，建议先浏览 <a href="https://maayuan.top/Started/Install.html" target="_blank" rel="noreferrer">下载与安装</a> 与 <a href="https://maayuan.top/Started/FirstLaunch.html" target="_blank" rel="noreferrer">首次启动</a>。如果还是有问题，再来查阅本页面。</p></div><h2 id="下载相关" tabindex="-1">下载相关 <a class="header-anchor" href="#下载相关" aria-label="Permalink to “下载相关”">​</a></h2><h3 id="下载哪个安装包" tabindex="-1">下载哪个安装包 <a class="header-anchor" href="#下载哪个安装包" aria-label="Permalink to “下载哪个安装包”">​</a></h3><ul><li>完整版命名规则：<code>MaaYuan-版本-平台-架构.zip</code>（如 <code>MaaYuan-*-win-x64.zip</code>），其他为零部件。</li><li>具体下载详细操作请参阅考<a href="https://maayuan.top/Started/Install.html#download-channels" target="_blank" rel="noreferrer">新手教学</a>。</li></ul><h3 id="文件下载速度慢" tabindex="-1"><strong>文件下载速度慢</strong> <a class="header-anchor" href="#文件下载速度慢" aria-label="Permalink to “文件下载速度慢”">​</a></h3><p>更换其他网盘下载，或使用Mirror酱。</p><h2 id="安装相关" tabindex="-1">安装相关 <a class="header-anchor" href="#安装相关" aria-label="Permalink to “安装相关”">​</a></h2><h3 id="运行库问题" tabindex="-1"><strong>运行库问题</strong> <a class="header-anchor" href="#运行库问题" aria-label="Permalink to “运行库问题”">​</a></h3><p>请确认是否已安装正确的运行库，详细操作请参阅<a href="https://maayuan.top/Started/Install.html#%E5%AE%89%E8%A3%85%E8%BF%90%E8%A1%8C%E7%8E%AF%E5%A2%83-%E4%BE%9D%E8%B5%96%E5%BA%93" target="_blank" rel="noreferrer">新手教学</a>。</p><h3 id="系统问题" tabindex="-1"><strong>系统问题</strong> <a class="header-anchor" href="#系统问题" aria-label="Permalink to “系统问题”">​</a></h3><ul><li><code>MaaYuan</code>不支持 32 位操作系统，不支持 Windows 7 / 8 / 8.1。</li><li>安装依赖系统组件（CBS/TrustedInstaller/WinSxS），若组件损坏需重装系统，请避免使用精简版或老旧系统。</li></ul><h3 id="文件下载速度慢-1" tabindex="-1"><strong>文件下载速度慢</strong> <a class="header-anchor" href="#文件下载速度慢-1" aria-label="Permalink to “文件下载速度慢”">​</a></h3><p>更换其他网盘下载，或使用Mirror酱。</p><h2 id="更新相关" tabindex="-1">更新相关 <a class="header-anchor" href="#更新相关" aria-label="Permalink to “更新相关”">​</a></h2><h3 id="更新版本出现问题" tabindex="-1">更新版本出现问题 <a class="header-anchor" href="#更新版本出现问题" aria-label="Permalink to “更新版本出现问题”">​</a></h3><ul><li><p>后台彻底关闭<code>MaaYuan</code>，释放adb。</p><ul><li>右键任务栏 → 任务管理器（或 Ctrl+Shift+Esc）→ 找到 adb → 结束任务。</li></ul></li><li><p>仍失败的话，您可以选择删除旧版本，直接下载最新版本压缩包使用。</p></li></ul><h3 id="mirror酱是什么" tabindex="-1">Mirror酱是什么 <a class="header-anchor" href="#mirror酱是什么" aria-label="Permalink to “Mirror酱是什么”">​</a></h3><ul><li><code>Mirror酱</code>是一个第三方应用分发平台，让开源应用的更新更简单。用户付费使用，收益与开发者共享。</li><li><code>MaaYuan</code>官方合作伙伴。</li><li>不用借助其他工具，即可开启<code>MaaYuan</code>自动更新服务。</li></ul><h3 id="什么时候要更新" tabindex="-1">什么时候要更新 <a class="header-anchor" href="#什么时候要更新" aria-label="Permalink to “什么时候要更新”">​</a></h3><ul><li>当下个版本适配新出活动时；</li><li>当前版本运行出现失误/故障等情况时。</li></ul><h3 id="大版本更新方式" tabindex="-1">大版本更新方式 <a class="header-anchor" href="#大版本更新方式" aria-label="Permalink to “大版本更新方式”">​</a></h3><p>更新方式有两种，内置资源自动更新和外部下载手动更新，详细操作请参阅<a href="https://maayuan.top/Started/ConnectionAndUpdate.html#%E6%9B%B4%E6%96%B0%E8%AE%BE%E7%BD%AE" target="_blank" rel="noreferrer">新手教学</a>。</p><h2 id="启动报错" tabindex="-1">启动报错 <a class="header-anchor" href="#启动报错" aria-label="Permalink to “启动报错”">​</a></h2><h3 id="报错信息-mfa遇到了问题" tabindex="-1">报错信息：MFA遇到了问题... <a class="header-anchor" href="#报错信息-mfa遇到了问题" aria-label="Permalink to “报错信息：MFA遇到了问题...”">​</a></h3><p>请看<a href="https://docs.qq.com/aio/DS1BMQmpiQkdOb1RT?p=lhxkpB2LdGdOmS3gQyArmB#rhyUl9GUKymFPSB4b6128k" target="_blank" rel="noreferrer">常见问题</a>。</p><h3 id="报错信息-无法加载dll" tabindex="-1">报错信息：无法加载DLL <a class="header-anchor" href="#报错信息-无法加载dll" aria-label="Permalink to “报错信息：无法加载DLL”">​</a></h3><ul><li>确保在解压后的原文件夹内运行<code>MaaYuan.exe</code>（非快捷方式，勿拖至桌面）；</li><li>请看<a href="https://docs.qq.com/aio/DS1BMQmpiQkdOb1RT?p=lhxkpB2LdGdOmS3gQyArmB#rhyUl9GUKymFPSB4b6128k" target="_blank" rel="noreferrer">常见问题</a>。</li></ul><h3 id="报错信息-此应用无法在你的电脑上运行" tabindex="-1">报错信息：此应用无法在你的电脑上运行 <a class="header-anchor" href="#报错信息-此应用无法在你的电脑上运行" aria-label="Permalink to “报错信息：此应用无法在你的电脑上运行”">​</a></h3><p>误下了ARM64版本（不兼容 Windows x64），请重新下载文件名含 <code>MaaYuan-*-win-x64.zip</code> 的压缩包。</p><h3 id="报错信息-xx异常" tabindex="-1">报错信息：XX异常 <a class="header-anchor" href="#报错信息-xx异常" aria-label="Permalink to “报错信息：XX异常”">​</a></h3><p>未安装完整 .NET 运行库，下载安装后重试。</p><h3 id="报错信息-未能加载文件" tabindex="-1">报错信息：未能加载文件 <a class="header-anchor" href="#报错信息-未能加载文件" aria-label="Permalink to “报错信息：未能加载文件”">​</a></h3><p>系统版本过旧不支持运行库，请更新系统。</p><h3 id="报错信息-检测资源-错误" tabindex="-1">报错信息：检测资源...错误 <a class="header-anchor" href="#报错信息-检测资源-错误" aria-label="Permalink to “报错信息：检测资源...错误”">​</a></h3><p>请检查联网设备的DNS，或魔法工具。</p>',35))])}const P=t(s,[["render",p]]);export{_ as __pageData,P as default};
